<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useAuthStore } from '../stores/auth.js'
import { useWorkspaceStore } from '../stores/workspace.js'
import { apiGet } from '../services/api.js'
import { formatDateTime } from '../utils/workflow.js'
import DashboardView from './DashboardView.vue'
import NursingWorklistView from './NursingWorklistView.vue'
import AppIcon from '../components/AppIcon.vue'
import AppointmentCard from '../components/AppointmentCard.vue'
const auth = useAuthStore(), workspace = useWorkspaceStore()
const clinical = computed(() => ['doctor', 'nurse'].includes(auth.user.role))
const beneficiary = computed(() => ['worker', 'dependent'].includes(auth.user.role))
const navigatorRole = computed(() => auth.user.role === 'navigator')
const busy = ref(false), error = ref(''), info = ref(null), campaigns = ref([]), ready = ref(false)
const firstName = computed(() => auth.user.name.split(' ')[0])
const nextAppointment = computed(() => info.value?.appointments?.filter(a => ['expected', 'confirmed'].includes(a.status)).sort((a, b) => a.scheduled_at.localeCompare(b.scheduled_at)).find(a => a.scheduled_at >= new Date().toLocaleString('sv-SE', { timeZone: 'America/Bahia' }).slice(0, 16)) || info.value?.appointments?.find(a => a.status === 'expected'))
const pending = computed(() => info.value?.beneficiaries?.filter(b => b.status === 'pending') || [])
async function load() {
  if (clinical.value) return
  busy.value = true; error.value = ''
  try {
    if (beneficiary.value) { const [appointments, ownCampaigns] = await Promise.all([apiGet('/me/appointments'), apiGet('/me/campaigns')]); info.value = { appointments }; campaigns.value = ownCampaigns }
    else if (navigatorRole.value) { const [returns, pipeline] = await Promise.all([apiGet('/continuity/dashboard'), apiGet('/engagement/pipeline')]); info.value = { ...returns, pipeline } }
    else { await workspace.ensure(auth.user); const q = '?' + new URLSearchParams({ company_id: workspace.companyId }); const [overview, cycles] = await Promise.all([apiGet('/management/overview' + q), apiGet('/management/campaigns' + q)]); info.value = overview; campaigns.value = cycles }
  } catch (e) { info.value = null; error.value = e.message } finally { busy.value = false }
}
watch(() => workspace.companyId, () => { if (ready.value && !clinical.value) load() })
onMounted(async () => { await load(); ready.value = true })
</script>
<template><NursingWorklistView v-if="auth.user.role === 'nurse'" /><DashboardView v-else-if="clinical" /><template v-else>
  <div class="page-heading"><div><p class="eyebrow">{{ beneficiary ? 'MEU CUIDADO' : navigatorRole ? 'ACOLHIMENTO E CONTINUIDADE' : 'SESI · INDÚSTRIA E FAMÍLIAS' }}</p><h1>Olá, {{ firstName }}.</h1><p class="text-secondary mb-0">{{ beneficiary ? 'Seu próximo passo de cuidado, sem complicação.' : navigatorRole ? 'Veja quem precisa de apoio e continue de onde parou.' : 'O que precisa da sua atenção hoje?' }}</p></div><RouterLink v-if="!beneficiary && !navigatorRole" class="btn btn-success" to="/management?new=invite"><AppIcon name="plus" :size="18" /> Convidar pessoa</RouterLink></div>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }} <button class="btn btn-sm btn-link" @click="load">Tentar novamente</button></p><p v-if="busy && !info" class="loading-state" role="status"><span class="spinner-border spinner-border-sm" /> Preparando seu espaço…</p>
  <template v-if="beneficiary"><div class="welcome-hero"><div><span class="soft-tag">Presencial e teleconsulta</span><h2>Seu cuidado também merece<br>um lugar na rotina.</h2><p>Encontre atendimento perto de você ou da indústria. Se precisar, sua equipe ajuda a organizar o retorno.</p><RouterLink to="/find-care" class="btn btn-success btn-lg">Encontrar atendimento <AppIcon name="arrow" /></RouterLink></div><div class="hero-symbol" aria-hidden="true"><AppIcon name="heart" :size="110" /></div></div><section class="card card-body mt-4"><div class="section-heading"><h2 class="h5">Seu próximo atendimento</h2><RouterLink to="/find-care">Ver todos</RouterLink></div><AppointmentCard v-if="nextAppointment" :appointment="nextAppointment" @refresh="load" @support="a => $router.push(`/find-care?support=${a.id}`)" /><div v-else class="empty-state"><AppIcon name="calendar" :size="32" /><p class="mb-2">Nenhum atendimento pendente por aqui.</p><RouterLink to="/find-care">Buscar um horário disponível →</RouterLink></div></section><div class="row g-4 mt-1"><div class="col-lg-6"><RouterLink to="/my-care" class="action-card"><span class="action-icon"><AppIcon name="book" :size="26" /></span><div><h2 class="h5">Conteúdos rápidos para você</h2><p>Como usar a plataforma e continuar seu acompanhamento, no seu ritmo.</p></div><AppIcon name="arrow" /></RouterLink></div><div class="col-lg-6"><RouterLink to="/my-care" class="action-card"><span class="action-icon amber"><AppIcon name="cycle" :size="26" /></span><div><h2 class="h5">Campanhas e próximos ciclos</h2><p>{{ campaigns.length ? `${campaigns.length} ciclo(s) disponível(is) para você conhecer.` : 'Veja os convites da sua indústria e participe quando fizer sentido.' }}</p></div><AppIcon name="arrow" /></RouterLink></div></div></template>
  <template v-else-if="navigatorRole && info"><div class="task-strip"><RouterLink to="/continuity"><strong>{{ info.metrics.pending }}</strong><span>retornos pendentes</span></RouterLink><RouterLink to="/engagement"><strong>{{ info.pipeline.filter(p => p.tasks.some(t => t.status === 'open')).length }}</strong><span>pessoas com próximo passo</span></RouterLink><RouterLink to="/continuity"><strong>{{ info.metrics.reconnected }}</strong><span>reconexões registradas</span></RouterLink></div><section class="card card-body"><div class="section-heading"><h2 class="h5">Retornos que precisam de acolhimento</h2><RouterLink to="/continuity">Ver todos</RouterLink></div><div v-for="c in info.cases.filter(c => c.status === 'pending').slice(0, 6)" :key="c.id" class="list-entry"><span class="avatar">{{ c.patient_name[0] }}</span><div><strong>{{ c.patient_name }}</strong><small>{{ formatDateTime(c.scheduled_at) }}</small></div><RouterLink :to="`/continuity?case=${c.id}`" class="btn btn-sm btn-success ms-auto">Acolher</RouterLink></div><p v-if="!info.metrics.pending" class="empty-state">Nenhum retorno pendente neste período.</p></section></template>
  <template v-else-if="info"><div v-if="workspace.companies.length > 1" class="context-bar"><AppIcon name="building" /><label for="home-company" class="visually-hidden">Indústria</label><select id="home-company" v-model="workspace.companyId" class="form-select" :disabled="busy"><option v-for="c in workspace.companies" :key="c.id" :value="c.id">{{ c.name }}</option></select></div><p v-else class="context-caption"><AppIcon name="building" :size="16" /> {{ workspace.companies[0]?.name }}</p>
  <div class="task-strip"><RouterLink to="/management"><strong>{{ pending.length }}</strong><span>cadastros para validar</span><AppIcon name="arrow" :size="16" /></RouterLink><RouterLink to="/management"><strong>{{ info.beneficiaries.length }}</strong><span>pessoas cadastradas</span></RouterLink><RouterLink to="/management?tab=contracts"><strong>{{ info.contracts.filter(c => c.status === 'active').length }}</strong><span>contratos ativos</span></RouterLink><RouterLink to="/campaign-management"><strong>{{ campaigns.filter(c => c.status === 'active').length }}</strong><span>campanhas em andamento</span></RouterLink></div>
  <div class="row g-4"><section class="col-xl-7"><div class="card card-body h-100"><div class="section-heading"><div><h2 class="h5 mb-1">Pendências de cadastro</h2><p class="small text-secondary mb-0">Contato e vínculo precisam de verificação antes de agendar.</p></div><RouterLink to="/management">Ver pessoas</RouterLink></div><div v-for="b in pending.slice(0, 5)" :key="b.id" class="list-entry"><span class="avatar">{{ b.name[0] }}</span><div><strong>{{ b.name }}</strong><small>{{ b.kind === 'worker' ? 'Trabalhador' : 'Dependente' }}</small></div><RouterLink :to="`/management?review=${b.id}`" class="btn btn-sm btn-success ms-auto">Validar cadastro</RouterLink></div><div v-if="!pending.length" class="empty-state"><span class="success-mark"><AppIcon name="check" :size="28" /></span><strong>Tudo em dia por aqui.</strong><p>Nenhum cadastro aguardando validação.</p><RouterLink to="/management?new=invite" class="btn btn-outline-success">Convidar uma pessoa</RouterLink></div></div></section><section class="col-xl-5"><div class="card card-body h-100"><h2 class="h5 mb-4">Resolver agora</h2><RouterLink to="/management?new=invite" class="command-result"><span class="action-icon"><AppIcon name="people" /></span><span><strong>Convidar trabalhador ou dependente</strong><small>Link de cadastro pronto para compartilhar</small></span><AppIcon name="arrow" /></RouterLink><RouterLink to="/campaign-management?new=campaign" class="command-result"><span class="action-icon amber"><AppIcon name="cycle" /></span><span><strong>Criar um ciclo de campanha</strong><small>Conteúdos e público em um só lugar</small></span><AppIcon name="arrow" /></RouterLink><RouterLink to="/education-editor?new=content" class="command-result"><span class="action-icon"><AppIcon name="book" /></span><span><strong>Preparar conteúdo rápido</strong><small>Roteiro, vídeo e revisão</small></span><AppIcon name="arrow" /></RouterLink><RouterLink v-if="auth.user.role === 'admin'" to="/management?new=slot" class="command-result"><span class="action-icon"><AppIcon name="calendar" /></span><span><strong>Disponibilizar atendimento</strong><small>Presencial ou teleconsulta</small></span><AppIcon name="arrow" /></RouterLink></div></section></div>
  <p class="privacy-note"><AppIcon name="heart" :size="16" /> Esta visão é administrativa. Prontuários e histórico individual de conteúdos permanecem restritos.</p></template>
</template></template>
